//
// simple simplex noise (c) Stefan Gustavson,
// ver. 2025-01-22, published under CC-BY-SA 4.0
// https://creativecommons.org/licenses/by-sa/4.0/
//

// Different permutation polynomials for x and y to avoid artifacts
vec3 hash(vec3 ix, vec3 iy) {
  ix = mod(ix, 289.0);
  vec3 h = mod((ix*51.0 + 2.0)*ix + iy, 289.0); // 51x^2 + 2x
  return mod((h*34.0 + 10.0)*h, 289.0); // 34x^2 + 10x
}

// A bare-bones simplex noise function in 2-D
float ssnoise(vec2 p)
{
    // Staggered grid, points at integer y and integer/half x
    // (Yields a slightly non-uniform triangular/hex grid.)
    vec2 uv = vec2(p.x+p.y*0.5, p.y) + 1e-4; // Transform to skewed space
    vec2 i0 = floor(uv); // Which grid rhombus are we in?
    vec2 f0 = fract(uv); // And which of the two triangles?
    float cmp = step(f0.y, f0.x); // Equivalent to "(f0.y>f0.x)?1.0:0.0"
    vec2 o1 = vec2(cmp, 1.0-cmp); // o1 is the offset to the second corner
    vec2 i1 = i0 + o1, i2 = i0 + 1.0; // Grid coordinates, used for hash
    vec2 p0 = vec2(i0.x - i0.y*0.5, i0.y); // Transform back to p space
    vec2 p1 = vec2(p0.x + o1.x - o1.y*0.5, p0.y + o1.y);
    vec2 p2 = vec2(p0.x + 0.5, p0.y + 1.0);
    vec2 v0 = p - p0, v1 = p - p1, v2 = p - p2; // Vectors from corners to p

    // Compute a simple hash for each of the three corners
    // Hash with permutation polynomials (floating-point math)
    vec3 iu = vec3(i0.x, i1.x, i2.x); // Hash coords
    vec3 iv = vec3(i0.y, i1.y, i2.y);
    vec3 h = hash(iu, iv);
    vec3 psi = h*0.07482; // Scale the hash (and jumble it some more)

    // Generate three gradients
    vec3 gx = cos(psi); // sin and cos are usually fast these days
    vec3 gy = sin(psi);
    vec2 g0 = vec2(gx.x, gy.x);
    vec2 g1 = vec2(gx.y, gy.y);
    vec2 g2 = vec2(gx.z, gy.z);

    // Compute the kernels of influence from each corner
    // The radial decay part
    vec3 w = 0.8 - vec3(dot(v0, v0), dot(v1, v1), dot(v2, v2));
    w = max(w, 0.0); // Cut off the negative part
    vec3 w2 = w*w;
    vec3 w4 = w2*w2; // This is our radial weight
    // The extrapolated linear ramp part
    vec3 gdotv = vec3(dot(g0, v0), dot(g1, v1), dot(g2, v2));
    // Compute and sum up the three contributions in one go
    float n = dot(w4, gdotv);

    // Scale the noise value to span the range [1,1]
    return 10.9*n;
}

//
// Classic 2-D Perlin noise, optimized for speed.
// Copyright (c) 2011, 2025 Stefan Gustavson.
// Distributed under the MIT license.
// https://github.com/stegu/webgl-noise
//

// Different permutation polynomials for x and y to avoid artifacts
vec4 hash(vec4 ix, vec4 iy) {
  ix = mod(ix, 289.0);
  vec4 h = mod((ix*51.0 + 2.0)*ix + iy, 289.0); // 51x^2 + 2x
  return mod((h*34.0 + 10.0)*h, 289.0); // 34x^2 + 10x
}
// A fifth degree interpolating function to replace the cubic interpolation
vec2 fade(vec2 t) {
  return t*t*t*(t*(t*6.0-15.0)+10.0); // Better than (3.0-2.0*t)*t*t
}

// Classic Perlin noise in 2-D
float cnoise(vec2 P) {
	vec4 Pi = floor(P.xyxy) + vec4(0.0, 0.0, 1.0, 1.0);
	vec4 Pf = fract(P.xyxy) - vec4(0.0, 0.0, 1.0, 1.0);
	Pi = mod(Pi, 289.0); // mod to avoid truncation in permutation
	vec4 ix = Pi.xzxz;
	vec4 iy = Pi.yyww;
	vec4 fx = Pf.xzxz;
	vec4 fy = Pf.yyww;
	// Generate hash values for all four corners
	vec4 i = hash(ix, iy);
    // Generate four gradients
    vec4 psi = i*0.07482; // Scale and jumble some more
    vec4 gx = cos(psi); // sin and cos are
    vec4 gy = sin(psi); // usually fast these days
	vec2 g00 = vec2(gx.x, gy.x);
	vec2 g10 = vec2(gx.y, gy.y);
	vec2 g01 = vec2(gx.z, gy.z);
	vec2 g11 = vec2(gx.w, gy.w);
	// Extrapolated contributions from each corner
	float n00 = dot(g00, vec2(fx.x, fy.x));
	float n10 = dot(g10, vec2(fx.y, fy.y));
	float n01 = dot(g01, vec2(fx.z, fy.z));
	float n11 = dot(g11, vec2(fx.w, fy.w));
	// Interpolations in x and y
	vec2 fade_xy = fade(Pf.xy);
	vec2 n_x = mix(vec2(n00, n01), vec2(n10, n11), fade_xy.x);
	float n = mix(n_x.x, n_x.y, fade_xy.y);
	return 1.58 * n; // Empirical scaling factor, output covers [-1,1]
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from -1 to 1 in the shortest direction)
    vec2 uv = (2.0*fragCoord-iResolution.xy)/min(iResolution.x, iResolution.y);

    float cn = 0.5 + 0.5*cnoise(uv*13.0); // Visual match of feature sizes
    float sn = 0.5 + 0.4*ssnoise(uv*10.0); // Visual match of average contrast

    vec3 col = vec3(uv.x < 0.0 ? sn : cn);
    fragColor = vec4(col,1.0);
}
